163			return
164		}
165		if existing, found, err := h.findExistingImport(r.Context(), owner, repo); err != nil {
166			writeAnyError(w, err)
167			return
168		} else if found {
169			writeExistingImport(w, existing, req.RepoURL, req.DefaultBranch)
170			return
171		}
172	
173		// Validate the GitHub source and read workspace metadata so the HTTP request
174		// can return quickly while full reconciliation runs in the background worker.
175		snap, err := h.github.FetchWorkspaceMetadata(r.Context(), domain.ImportInput{
176			RepoURL:       req.RepoURL,
177			DefaultBranch: req.DefaultBranch,
178			Token:         h.token,
179		})
180		if err != nil {
181			writeAnyError(w, err)
182			return
183		}
184	
185		workspaceID := uuid.NewString()
186		name := strings.TrimSpace(req.Name)
187		if name == "" {
188			name = snap.Name
189		}
190		if name == "" {
191			name = owner + "/" + repo
192		}
193		slug := slugify(name)
194		if slug == "" {
195			slug = workspaceID
196		}
197	
198		workspaceID, err = h.createImportPlaceholder(r.Context(), workspaceID, name, slug, req.RepoURL, req.DefaultBranch, snap.ManagementRepoID)
199		if err != nil {
200			// Only attempt the duplicate-detection fallback for unique constraint violations.
201			// For infrastructure errors (connection failure, timeout) we return immediately
202			// so they are not masked by a second failing query.
203			if !isUniqueViolation(err) {
204				writeAnyError(w, err)
205				return
206			}
207			if existing, found, findErr := h.findExistingImport(r.Context(), owner, repo); findErr != nil {
208				writeAnyError(w, findErr)
209				return
210			} else if found {
211				writeExistingImport(w, existing, req.RepoURL, req.DefaultBranch)
212				return
213			}
214			if isUniqueConstraintViolation(err, "workspaces_slug_unique") {
215				writeSourceError(w, domain.NewDatabaseConflictError(fmt.Sprintf("workspace slug %q already exists for another GitHub repository", slug)))
216				return
217			}
218			writeAnyError(w, err)
219			return
220		}
221		run, err := h.insertRunningRun(r.Context(), workspaceID, "api_import", "full", req.DefaultBranch)
222		if err != nil {
223			writeAnyError(w, err)
224			return
225		}
