337	// webhookHandler processes GitHub push event webhooks.
338	// It verifies the HMAC signature, parses the push payload, and routes based on branch:
339	//   - base branch → enqueue targeted sync for touched features
340	//   - feature branch → enqueue targeted workspace:sync for that feature
341	//   - task branch → enqueue task:sync with dedup
342	//   - other → 200 OK, ignored
343	func (h *serviceHandler) webhookHandler(w http.ResponseWriter, r *http.Request) {
344		if r.Method != http.MethodPost {
345			w.Header().Set("Allow", http.MethodPost)
346			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
347			return
348		}
349	
350		body, err := webhook.ReadAndVerify(r, h.webhookSecret)
351		if err != nil {
352			http.Error(w, "signature verification failed: "+err.Error(), http.StatusUnauthorized)
353			return
354		}
355	
356		// Only handle push events; ignore other event types gracefully.
357		eventType := r.Header.Get("X-GitHub-Event")
358		if eventType != "push" {
359			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "event": eventType})
360			return
361		}
362	
363		ev, err := webhook.ParsePushEvent(body)
364		if err != nil {
365			http.Error(w, "invalid push event payload", http.StatusBadRequest)
366			return
367		}
368	
369		branch := webhook.BranchFromRef(ev.Ref)
370	
371		// Look up the workspace by repo URL to find workspaceID, defaultBranch, and branchPattern.
372		repoURL := ev.Repository.CloneURL
373		if repoURL == "" {
374			repoURL = ev.Repository.HTMLURL
375		}
376		wsInfo, dbErr := h.findWorkspaceByRepoURL(r.Context(), repoURL)
377		if dbErr != nil {
378			// Unknown repo — not an error from our side, just ignore.
379			log.Printf("webhook: repo not registered: %s", repoURL)
380			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "reason": "repo not registered"})
381			return
382		}
383	
384		info := webhook.ClassifyBranch(branch, wsInfo.defaultBranch, wsInfo.branchPattern)
385		switch info.Kind {
386		case webhook.BranchIgnored:
387			writeJSON(w, http.StatusOK, map[string]string{"status": "ignored", "branch": branch})
388			return
389	
390		case webhook.BranchBase:
391			payloads := basePushTargetedSyncPayloads(wsInfo, branch, ev)
392			if len(payloads) == 0 {
393				writeJSON(w, http.StatusOK, map[string]string{
394					"status":      "ignored",
395					"branch_kind": "base",
396					"reason":      "no feature artifact paths",
397				})
398				return
399			}
400			if err := h.enqueueWorkspaceSyncs(payloads); err != nil {
401				log.Printf("webhook: enqueue base targeted sync failed workspace=%s branch=%s: %v",
402					wsInfo.workspaceID, branch, err)
403				http.Error(w, "enqueue targeted sync failed", http.StatusServiceUnavailable)
404				return
405			}
406			writeJSON(w, http.StatusOK, map[string]string{
407				"status":      "queued",
408				"branch_kind": "base",
409				"mode":        "targeted",
410			})
411	
412		case webhook.BranchFeature:
413			if err := h.enqueueTargetedSync(wsInfo, info.FeatureID, branch, "webhook_feature"); err != nil {
414				log.Printf("webhook: enqueue feature targeted sync failed workspace=%s feature=%s: %v",
415					wsInfo.workspaceID, info.FeatureID, err)
416				http.Error(w, "enqueue targeted sync failed", http.StatusServiceUnavailable)
417				return
418			}
419			writeJSON(w, http.StatusOK, map[string]string{
420				"status":      "queued",
421				"branch_kind": "feature",
422				"feature_id":  info.FeatureID,
423			})
424	
425		case webhook.BranchTask:
426			if err := h.enqueueTaskSync(wsInfo.workspaceID, info.FeatureID, info.TaskID); err != nil {
427				log.Printf("webhook: enqueue task sync failed workspace=%s feature=%s task=%s: %v",
428					wsInfo.workspaceID, info.FeatureID, info.TaskID, err)
429				http.Error(w, "enqueue task sync failed", http.StatusServiceUnavailable)
430				return
431			}
432			writeJSON(w, http.StatusOK, map[string]string{
433				"status":      "queued",
434				"branch_kind": "task",
435				"feature_id":  info.FeatureID,
436				"task_id":     info.TaskID,
437			})
438		}
439	}
