441	func basePushTargetedSyncPayloads(ws *workspaceWebhookInfo, branch string, ev *webhook.PushEvent) []queue.WorkspaceSyncPayload {
442		featureIDs := webhook.TouchedFeatureIDs(ev)
443		payloads := make([]queue.WorkspaceSyncPayload, 0, len(featureIDs))
444		for _, featureID := range featureIDs {
445			payloads = append(payloads, queue.WorkspaceSyncPayload{
446				WorkspaceID:   ws.workspaceID,
447				RepoURL:       ws.repoURL,
448				DefaultBranch: ws.defaultBranch,
449				Ref:           branch,
450				Trigger:       "webhook_base",
451				Mode:          "targeted",
452				FeatureID:     featureID,
453			})
454		}
455		return payloads
456	}
457	
458	// workspaceWebhookInfo holds the minimal workspace data needed by webhook routing.
459	type workspaceWebhookInfo struct {
460		workspaceID   string
461		repoURL       string
462		defaultBranch string
463		branchPattern string
464	}
465	
466	// findWorkspaceByRepoURL queries the DB for a workspace matching the given repo URL.
467	func (h *serviceHandler) findWorkspaceByRepoURL(ctx context.Context, repoURL string) (*workspaceWebhookInfo, error) {
468		owner, repo, err := parseGitHubRepo(repoURL)
469		if err != nil {
470			return nil, err
471		}
472		src, dbError := h.q.GetGitHubSourceByRepo(ctx, database.GetGitHubSourceByRepoParams{
473			RepoOwner: owner,
474			RepoName:  repo,
475		})
476		if dbError != nil {
477			return nil, dbError
478		}
479		defaultBranch := "main"
480		if src.DefaultBranch != nil && *src.DefaultBranch != "" {
481			defaultBranch = *src.DefaultBranch
482		}
483		ws, err := h.q.GetWorkspace(ctx, src.WorkspaceID)
484		if err != nil {
485			return nil, fmt.Errorf("get webhook workspace: %w", err)
486		}
487		branchPattern := ""
488		if ws.BranchPattern != nil {
489			branchPattern = *ws.BranchPattern
490		}
491		return &workspaceWebhookInfo{
492			workspaceID:   uuidString(src.WorkspaceID),
493			repoURL:       src.RepoURL,
494			defaultBranch: defaultBranch,
495			branchPattern: branchPattern,
496		}, nil
497	}
498	
499	// enqueueTargetedSync enqueues a workspace:sync task with mode=targeted for a single feature.
500	func (h *serviceHandler) enqueueTargetedSync(ws *workspaceWebhookInfo, featureID, branch, trigger string) error {
501		payload := queue.WorkspaceSyncPayload{
502			WorkspaceID:   ws.workspaceID,
503			RepoURL:       ws.repoURL,
504			DefaultBranch: ws.defaultBranch,
505			Ref:           branch,
506			Trigger:       trigger,
507			Mode:          "targeted",
508			FeatureID:     featureID,
509		}
510		return h.enqueueWorkspaceSync(payload)
511	}
512	
513	func (h *serviceHandler) enqueueWorkspaceSyncs(payloads []queue.WorkspaceSyncPayload) error {
514		for _, payload := range payloads {
515			if err := h.enqueueWorkspaceSync(payload); err != nil {
516				return err
517			}
518		}
519		return nil
520	}
521	
522	func (h *serviceHandler) enqueueWorkspaceSync(payload queue.WorkspaceSyncPayload) error {
523		task, err := queue.NewWorkspaceSyncTask(payload)
524		if err != nil {
525			return fmt.Errorf("build workspace sync task: %w", err)
526		}
527		if _, err := h.queue.Enqueue(task, asynq.TaskID(workspaceSyncTaskID(payload))); err != nil {
528			if isDedupeError(err) {
529				return nil
530			}
531			return fmt.Errorf("enqueue workspace sync: %w", err)
532		}
533		return nil
534	}
535	
536	// enqueueTaskSync enqueues a task:sync job with deduplication.
537	func (h *serviceHandler) enqueueTaskSync(workspaceID, featureID, taskID string) error {
538		payload := queue.TaskSyncPayload{
539			WorkspaceID: workspaceID,
540			FeatureID:   featureID,
541			TaskID:      taskID,
542		}
543		task, err := queue.NewTaskSyncTask(payload)
544		if err != nil {
545			return fmt.Errorf("build task:sync task: %w", err)
546		}
547		info, err := h.queue.Enqueue(task)
548		if err != nil {
549			// ErrTaskIDConflict means duplicate — already queued, this is expected with Unique(24h).
550			if isDedupeError(err) {
551				log.Printf("task:sync already queued (dedup) workspace=%s feature=%s task=%s", workspaceID, featureID, taskID)
552				return nil
553			}
554			return fmt.Errorf("enqueue task:sync: %w", err)
555		}
556		log.Printf("task:sync enqueued id=%s workspace=%s feature=%s task=%s", info.ID, workspaceID, featureID, taskID)
557		return nil
558	}
559	
560	// isDedupeError returns true when the asynq error indicates a duplicate task (Unique constraint).
561	func isDedupeError(err error) bool {
562		return errors.Is(err, asynq.ErrDuplicateTask) || errors.Is(err, asynq.ErrTaskIDConflict) ||
563			(err != nil && strings.Contains(err.Error(), "task already exists"))
564	}
565	
566	// isUniqueViolation returns true when err is a PostgreSQL unique constraint violation (SQLSTATE 23505).
567	func isUniqueViolation(err error) bool {
568		var pgErr *pgconn.PgError
569		return errors.As(err, &pgErr) && pgErr.Code == "23505"
570	}
571	
572	func isUniqueConstraintViolation(err error, constraint string) bool {
573		var pgErr *pgconn.PgError
574		return errors.As(err, &pgErr) && pgErr.Code == "23505" && pgErr.ConstraintName == constraint
575	}
576	
577	func (h *serviceHandler) findExistingImport(ctx context.Context, owner, repo string) (database.Workspace, bool, error) {
578		src, err := h.q.GetGitHubSourceByRepo(ctx, database.GetGitHubSourceByRepoParams{
579			RepoOwner: owner,
580			RepoName:  repo,
581		})
582		if err != nil {
583			if errors.Is(err, pgx.ErrNoRows) {
584				return database.Workspace{}, false, nil
585			}
586			return database.Workspace{}, false, fmt.Errorf("get github source by repo: %w", err)
587		}
588		ws, err := h.q.GetWorkspace(ctx, src.WorkspaceID)
589		if err != nil {
590			return database.Workspace{}, false, fmt.Errorf("get existing imported workspace: %w", err)
591		}
592		return ws, true, nil
593	}
594	
595	func (h *serviceHandler) createImportPlaceholder(ctx context.Context, workspaceID, name, slug, repoURL, defaultBranch, managementRepoID string) (string, error) {
596		uid, err := pgUUID(workspaceID)
597		if err != nil {
598			return "", err
599		}
600		if h.pool == nil {
601			return h.createImportPlaceholderWithQueries(ctx, h.q, uid, name, slug, repoURL, defaultBranch, managementRepoID)
602		}
603	
604		tx, err := h.pool.BeginTx(ctx, pgx.TxOptions{})
605		if err != nil {
606			return "", fmt.Errorf("begin import placeholder transaction: %w", err)
607		}
608		defer tx.Rollback(ctx) //nolint:errcheck
609	
610		actualWorkspaceID, err := h.createImportPlaceholderWithQueries(ctx, h.q.WithTx(tx), uid, name, slug, repoURL, defaultBranch, managementRepoID)
611		if err != nil {
612			return "", err
613		}
614		if err := tx.Commit(ctx); err != nil {
615			return "", fmt.Errorf("commit import placeholder transaction: %w", err)
616		}
617		return actualWorkspaceID, nil
618	}
619	
620	func (h *serviceHandler) createImportPlaceholderWithQueries(ctx context.Context, q *database.Queries, uid pgtype.UUID, name, slug, repoURL, defaultBranch, managementRepoID string) (string, error) {
621		ws, err := q.UpsertWorkspaceByID(ctx, database.UpsertWorkspaceByIDParams{
622			ID:               uid,
623			Slug:             slug,
624			Name:             name,
625			ManagementRepoID: managementRepoID,
626		})
627		if err != nil {
628			return "", fmt.Errorf("upsert import placeholder workspace: %w", err)
629		}
630		actualWorkspaceID := uuidString(ws.ID)
631		if err := h.upsertGitHubSourceWithQueries(ctx, q, actualWorkspaceID, repoURL, defaultBranch); err != nil {
632			return "", err
633		}
634		return actualWorkspaceID, nil
635	}
636	
637	func (h *serviceHandler) upsertGitHubSourceWithQueries(ctx context.Context, q *database.Queries, workspaceID, repoURL, defaultBranch string) error {
638		uid, err := pgUUID(workspaceID)
639		if err != nil {
640			return err
641		}
642		owner, repo, err := parseGitHubRepo(repoURL)
643		if err != nil {
644			return err
645		}
646		_, err = q.UpsertGitHubSource(ctx, database.UpsertGitHubSourceParams{
647			WorkspaceID:   uid,
648			RepoURL:       repoURL,
649			RepoOwner:     owner,
650			RepoName:      repo,
651			DefaultBranch: &defaultBranch,
652		})
653		if err != nil {
654			return fmt.Errorf("upsert github source: %w", err)
655		}
656		return nil
657	}
658	
659	func (h *serviceHandler) insertRunningRun(ctx context.Context, workspaceID, trigger, mode, branch string) (database.WorkspaceSyncRun, error) {
660		uid, err := pgUUID(workspaceID)
661		if err != nil {
662			return database.WorkspaceSyncRun{}, err
663		}
664		branchPtr := branch
665		row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
666			WorkspaceID:  uid,
667			Trigger:      trigger,
668			Branch:       &branchPtr,
669			Mode:         mode,
670			Status:       "running",
671			ChangedPaths: []byte("[]"),
672		})
673		if err != nil {
674			return database.WorkspaceSyncRun{}, fmt.Errorf("insert sync run: %w", err)
675		}
676		return row, nil
677	}
678	
679	func (h *serviceHandler) markRunFailed(ctx context.Context, runID pgtype.UUID, code, message string) error {
680		_, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
681			ID:           runID,
682			ErrorCode:    &code,
683			ErrorMessage: &message,
684		})
685		if err != nil {
686			return fmt.Errorf("update sync run failed: %w", err)
687		}
688		return nil
689	}
690	
691	func workspaceSyncTaskID(payload queue.WorkspaceSyncPayload) string {
692		ref := payload.Ref
693		if ref == "" {
694			ref = payload.DefaultBranch
695		}
696		mode := payload.Mode
697		if mode == "" {
698			mode = "full"
699		}
700		raw := payload.WorkspaceID + "-" + payload.RepoURL + "-" + ref + "-" + mode + "-" + payload.FeatureID
701		id := slugify(raw)
702		if id == "" {
703			id = payload.WorkspaceID
704		}
705		return "workspace-sync-" + id
706	}
707	
708	func uuidString(uid pgtype.UUID) string {
709		return uuid.UUID(uid.Bytes).String()
710	}
711	
712	func slugify(name string) string {
713		lower := strings.ToLower(name)
714		re := regexp.MustCompile(`[^a-z0-9]+`)
715		slug := re.ReplaceAllString(lower, "-")
716		return strings.Trim(slug, "-")
717	}
718	
719	func workspaceIDFromSyncPath(path string) (string, bool) {
720		const prefix = "/internal/workspaces/"
721		const suffix = "/sync"
722		if !strings.HasPrefix(path, prefix) || !strings.HasSuffix(path, suffix) {
723			return "", false
724		}
725		workspaceID := strings.TrimSuffix(strings.TrimPrefix(path, prefix), suffix)
726		workspaceID = strings.Trim(workspaceID, "/")
727		return workspaceID, workspaceID != ""
728	}
729	
730	func pgUUID(raw string) (pgtype.UUID, error) {
731		var uid pgtype.UUID
732		if err := uid.Scan(raw); err != nil {
733			return pgtype.UUID{}, domain.NewValidationError(domain.ErrValidationMissingInput, "invalid workspace_id: "+raw)
734		}
735		return uid, nil
736	}
737	
738	func parseGitHubRepo(raw string) (string, string, error) {
739		u, err := url.Parse(raw)
740		if err != nil || u.Host == "" {
741			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL: "+raw)
742		}
743		if !strings.EqualFold(u.Host, "github.com") {
744			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "unsupported GitHub host: "+u.Host)
745		}
746		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
747		if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
748			return "", "", domain.NewValidationError(domain.ErrValidationInvalidURL, "invalid GitHub repo URL path: "+raw)
749		}
750		return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
751	}
752	
753	func writeAnyError(w http.ResponseWriter, err error) {
754		var se domain.SourceError
755		if errors.As(err, &se) {
756			writeSourceError(w, se)
757			return
758		}
759		writeSourceError(w, domain.NewDatabaseError(domain.ErrDatabaseQuery, err.Error()))
760	}
761	
762	func writeSourceError(w http.ResponseWriter, se domain.SourceError) {
763		status := http.StatusInternalServerError
764		switch se.Source {
765		case domain.ErrorSourceValidation:
766			status = http.StatusBadRequest
767		case domain.ErrorSourceGitHub:
768			switch se.Code {
769			case domain.ErrGitHubNotFound:
770				status = http.StatusNotFound
771			case domain.ErrGitHubUnauthorized:
772				status = http.StatusUnauthorized
773			case domain.ErrGitHubRateLimit:
774				status = http.StatusTooManyRequests
775			default:
776				status = http.StatusBadGateway
777			}
778		case domain.ErrorSourceDatabase:
779			switch se.Code {
780			case domain.ErrDatabaseNotFound:
781				status = http.StatusNotFound
782			case domain.ErrDatabaseConflict:
783				status = http.StatusConflict
784			}
785		}
786		writeJSON(w, status, domain.FromSourceError(se, nil))
787	}
788	
789	func writeExistingImport(w http.ResponseWriter, existing database.Workspace, repoURL, defaultBranch string) {
790		writeJSON(w, http.StatusOK, importWorkspaceResponse{
791			Status:        "exists",
792			WorkspaceID:   uuidString(existing.ID),
793			Name:          existing.Name,
794			Slug:          existing.Slug,
795			RepoURL:       repoURL,
796			DefaultBranch: defaultBranch,
797		})
798	}
799	
800	func writeJSON(w http.ResponseWriter, status int, value interface{}) {
801		w.Header().Set("Content-Type", "application/json")
802		w.WriteHeader(status)
803		_ = json.NewEncoder(w).Encode(value)
804	}
