91	func (h *handler) handleWorkspaceSync(ctx context.Context, t *asynq.Task) error {
92		var payload queue.WorkspaceSyncPayload
93		if err := json.Unmarshal(t.Payload(), &payload); err != nil {
94			return fmt.Errorf("unmarshal payload: %w", err)
95		}
96		if payload.RepoURL == "" {
97			return fmt.Errorf("repo_url is required: %w", asynq.SkipRetry)
98		}
99		if strings.TrimSpace(payload.WorkspaceID) == "" {
100			return fmt.Errorf("workspace_id is required for workspace sync: %w", asynq.SkipRetry)
101		}
102		if err := h.ensureWorkspaceExists(ctx, payload.WorkspaceID); err != nil {
103			return err
104		}
105		if payload.DefaultBranch == "" {
106			payload.DefaultBranch = "main"
107		}
108		ref := payload.Ref
109		if ref == "" {
110			ref = payload.DefaultBranch
111		}
112		trigger := payload.Trigger
113		if trigger == "" {
114			trigger = "redis_worker"
115		}
116		mode := payload.Mode
117		if mode == "" {
118			mode = "full"
119		}
120	
121		// Targeted sync: fetch and upsert a single feature only.
122		if mode == "targeted" && payload.FeatureID != "" {
123			return h.handleTargetedSync(ctx, payload, trigger, ref)
124		}
125	
126		// Full reconciliation: clear pending task-sync jobs first, then sync everything.
127		log.Printf("sync started workspace_id=%s repo_url=%s ref=%s", payload.WorkspaceID, payload.RepoURL, ref)
128	
129		// Delete all pending task-sync jobs before full reconciliation starts.
130		// The full read supersedes all queued partial updates.
131		inspector := h.openPendingTaskInspector()
132		defer func() {
133			if err := inspector.Close(); err != nil {
134				log.Printf("warn: close asynq inspector: %v", err)
135			}
136		}()
137		if _, err := clearPendingTaskSyncJobsForWorkspace(inspector, payload.WorkspaceID); err != nil {
138			err = fmt.Errorf("clear pending task-sync jobs for workspace %s: %w", payload.WorkspaceID, err)
139			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
140			return err
141		}
142	
143		snap, err := h.github.ImportWorkspace(ctx, domain.ImportInput{
144			RepoURL:       payload.RepoURL,
145			DefaultBranch: ref,
146			Token:         h.token,
147		})
148		if err != nil {
149			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
150			return err
151		}
152		if err := firstSnapshotSourceError(snap); err != nil {
153			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
154			return err
155		}
156		snap.WorkspaceID = payload.WorkspaceID
157		snap.RepoURL = payload.RepoURL
158		if strings.TrimSpace(payload.Name) != "" {
159			snap.Name = payload.Name
160			snap.Slug = slugify(payload.Name)
161		}
162	
163		if err := h.db.SaveSnapshot(ctx, payload.WorkspaceID, snap); err != nil {
164			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
165			return err
166		}
167		if err := h.upsertGitHubSource(ctx, payload.WorkspaceID, payload.RepoURL, payload.DefaultBranch); err != nil {
168			h.recordFailedRun(ctx, payload, trigger, mode, ref, err)
169			return err
170		}
171		if err := h.recordSuccessfulRun(ctx, payload, trigger, mode, ref, snap.CommitSHA); err != nil {
172			return err
