186	func clearPendingTaskSyncJobsForWorkspace(inspector pendingTaskInspector, workspaceID string) (int, error) {
187		const pageSize = 100
188		deleted := 0
189		page := 1
190		for {
191			tasks, err := inspector.ListPendingTasks(queue.QueueTaskSync, asynq.Page(page), asynq.PageSize(pageSize))
192			if errors.Is(err, asynq.ErrQueueNotFound) {
193				return deleted, nil
194			}
195			if err != nil {
196				return deleted, fmt.Errorf("list pending task-sync jobs: %w", err)
197			}
198			if len(tasks) == 0 {
199				return deleted, nil
200			}
201	
202			deletedFromPage := false
203			for _, info := range tasks {
204				if info.Type != queue.TypeTaskSync {
205					continue
206				}
207				var payload queue.TaskSyncPayload
208				if err := json.Unmarshal(info.Payload, &payload); err != nil {
209					continue
210				}
211				if payload.WorkspaceID != workspaceID {
212					continue
213				}
214				if err := inspector.DeleteTask(queue.QueueTaskSync, info.ID); err != nil {
215					return deleted, fmt.Errorf("delete pending task-sync job %s: %w", info.ID, err)
216				}
217				deleted++
218				deletedFromPage = true
219			}
220	
221			if deletedFromPage {
222				page = 1
223				continue
224			}
225			if len(tasks) < pageSize {
226				return deleted, nil
227			}
228			page++
229		}
230	}
