259		log.Printf("targeted sync finished workspace_id=%s feature_id=%s", payload.WorkspaceID, payload.FeatureID)
260		return nil
261	}
262	
263	// handleTaskSync processes task:sync jobs from the task-sync queue.
264	// It derives the source branch from workspace branch_pattern at drain time so
265	// duplicate webhook events always fetch the latest task branch HEAD.
266	func (h *handler) handleTaskSync(ctx context.Context, t *asynq.Task) error {
267		var payload queue.TaskSyncPayload
268		if err := json.Unmarshal(t.Payload(), &payload); err != nil {
269			return fmt.Errorf("unmarshal task sync payload: %w", err)
270		}
271		if payload.WorkspaceID == "" || payload.FeatureID == "" || payload.TaskID == "" {
272			return fmt.Errorf("task sync payload missing required fields: %+v", payload)
273		}
274	
275		log.Printf("task sync started workspace_id=%s feature_id=%s task_id=%s",
276			payload.WorkspaceID, payload.FeatureID, payload.TaskID)
277	
278		// Look up workspace to get repo_url and branch_pattern.
279		uid, err := pgUUID(payload.WorkspaceID)
280		if err != nil {
281			return err
282		}
283		ws, err := h.q.GetWorkspace(ctx, uid)
284		if err != nil {
285			return fmt.Errorf("get workspace for task sync: %w", err)
286		}
287		src, err := h.q.GetGitHubSource(ctx, uid)
288		if err != nil {
289			return fmt.Errorf("get github source for task sync: %w", err)
290		}
291	
292		// Derive the task branch from branch_pattern.
293		branchPattern := "feature/{feature_id}-{work_id}"
294		if ws.BranchPattern != nil && *ws.BranchPattern != "" {
295			branchPattern = *ws.BranchPattern
296		}
297		taskBranch := taskSyncBranch(payload, branchPattern)
298	
299		taskSnap, err := h.github.FetchTask(ctx, src.RepoURL, taskBranch, payload.FeatureID, payload.TaskID)
300		if err != nil {
301			h.recordTaskSyncFailed(ctx, payload, taskBranch, err)
302			return fmt.Errorf("fetch task %s/%s on branch %s: %w", payload.FeatureID, payload.TaskID, taskBranch, err)
303		}
304	
305		if err := h.db.SaveTaskSnapshot(ctx, payload.WorkspaceID, *taskSnap); err != nil {
306			h.recordTaskSyncFailed(ctx, payload, taskBranch, err)
307			return fmt.Errorf("save task snapshot %s/%s: %w", payload.FeatureID, payload.TaskID, err)
308		}
309		if err := h.recordTaskSyncSuccess(ctx, payload, taskBranch); err != nil {
310			return err
311		}
312	
313		log.Printf("task sync finished workspace_id=%s feature_id=%s task_id=%s",
314			payload.WorkspaceID, payload.FeatureID, payload.TaskID)
315		return nil
316	}
317	
318	func taskSyncBranch(payload queue.TaskSyncPayload, pattern string) string {
319		return deriveBranch(pattern, payload.FeatureID, payload.TaskID)
320	}
321	
322	// deriveBranch substitutes feature_id and task_id into a branch pattern.
323	// Pattern format: "feature/{feature_id}-{work_id}"
324	func deriveBranch(pattern, featureID, taskID string) string {
325		branch := pattern
326		branch = strings.ReplaceAll(branch, "{feature_id}", featureID)
327		branch = strings.ReplaceAll(branch, "{work_id}", taskID)
328		return branch
329	}
330	
331	func (h *handler) ensureWorkspaceExists(ctx context.Context, workspaceID string) error {
332		uid, err := pgUUID(workspaceID)
333		if err != nil {
334			return fmt.Errorf("%w: %w", err, asynq.SkipRetry)
335		}
336		if h.q == nil {
337			return nil
338		}
339		if _, err := h.q.GetWorkspace(ctx, uid); err != nil {
340			if errors.Is(err, pgx.ErrNoRows) {
341				return fmt.Errorf("workspace not found: %s: %w", workspaceID, asynq.SkipRetry)
342			}
343			return fmt.Errorf("get workspace before sync: %w", err)
344		}
345		return nil
346	}
347	
348	func (h *handler) recordTaskSyncSuccess(ctx context.Context, payload queue.TaskSyncPayload, branch string) error {
349		runID, err := h.ensureTaskSyncRun(ctx, payload, branch, true)
350		if err != nil {
351			return err
352		}
353		_, err = h.q.UpdateSyncRunSuccess(ctx, database.UpdateSyncRunSuccessParams{
354			ID: runID,
355		})
356		if err != nil {
357			return fmt.Errorf("update task sync run success: %w", err)
358		}
359		return nil
360	}
361	
362	func (h *handler) recordTaskSyncFailed(ctx context.Context, payload queue.TaskSyncPayload, branch string, syncErr error) {
363		code := "WORKER_TASK_SYNC_FAILED"
364		message := syncErr.Error()
365		var sourceErr domain.SourceError
366		if errors.As(syncErr, &sourceErr) {
367			code = string(sourceErr.Code)
368			message = sourceErr.Message
369		}
370		runID, err := h.ensureTaskSyncRun(ctx, payload, branch, false)
371		if err != nil {
372			log.Printf("ensure failed task sync run failed workspace_id=%s feature_id=%s task_id=%s error=%v original_error=%v",
373				payload.WorkspaceID, payload.FeatureID, payload.TaskID, err, syncErr)
374			return
375		}
376		if _, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
377			ID:           runID,
378			ErrorCode:    &code,
379			ErrorMessage: &message,
380		}); err != nil {
381			log.Printf("update failed task sync run failed workspace_id=%s feature_id=%s task_id=%s error=%v original_error=%v",
382				payload.WorkspaceID, payload.FeatureID, payload.TaskID, err, syncErr)
383		}
384	}
385	
386	func (h *handler) ensureTaskSyncRun(ctx context.Context, payload queue.TaskSyncPayload, branch string, requireRefs bool) (pgtype.UUID, error) {
387		uid, err := pgUUID(payload.WorkspaceID)
388		if err != nil {
389			return pgtype.UUID{}, err
390		}
391		featureUUID, taskUUID, err := h.syncRunReferenceIDs(ctx, uid, payload.FeatureID, payload.TaskID)
392		if err != nil {
393			if requireRefs {
394				return pgtype.UUID{}, err
395			}
396			log.Printf("warn: could not resolve task sync run refs workspace_id=%s feature_id=%s task_id=%s: %v",
397				payload.WorkspaceID, payload.FeatureID, payload.TaskID, err)
398			featureUUID = pgtype.UUID{}
399			taskUUID = pgtype.UUID{}
400		}
401		branchPtr := branch
402		row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
403			WorkspaceID:  uid,
404			Trigger:      "webhook_task",
405			Branch:       &branchPtr,
406			FeatureID:    featureUUID,
407			TaskID:       taskUUID,
408			Mode:         "task",
409			Status:       "running",
410			ChangedPaths: []byte("[]"),
411		})
412		if err != nil {
413			return pgtype.UUID{}, fmt.Errorf("insert task sync run: %w", err)
414		}
415		return row.ID, nil
416	}
417	
418	func (h *handler) syncRunReferenceIDs(ctx context.Context, workspaceID pgtype.UUID, featureName, taskName string) (pgtype.UUID, pgtype.UUID, error) {
419		var featureUUID pgtype.UUID
420		var taskUUID pgtype.UUID
421		if strings.TrimSpace(featureName) == "" {
422			return featureUUID, taskUUID, nil
423		}
424		feature, err := h.q.GetWorkspaceFeatureByName(ctx, database.GetWorkspaceFeatureByNameParams{
425			WorkspaceID: workspaceID,
426			FeatureName: featureName,
427		})
428		if err != nil {
429			return pgtype.UUID{}, pgtype.UUID{}, fmt.Errorf("resolve sync run feature ref %s: %w", featureName, err)
430		}
431		featureUUID = feature.ID
432		if strings.TrimSpace(taskName) == "" {
433			return featureUUID, taskUUID, nil
434		}
435		task, err := h.q.GetWorkspaceTaskByName(ctx, database.GetWorkspaceTaskByNameParams{
436			WorkspaceID: workspaceID,
437			FeatureID:   featureUUID,
438			TaskName:    taskName,
439		})
440		if err != nil {
441			return pgtype.UUID{}, pgtype.UUID{}, fmt.Errorf("resolve sync run task ref %s/%s: %w", featureName, taskName, err)
442		}
443		taskUUID = task.ID
444		return featureUUID, taskUUID, nil
445	}
446	
447	func (h *handler) upsertGitHubSource(ctx context.Context, workspaceID, repoURL, defaultBranch string) error {
448		uid, err := pgUUID(workspaceID)
449		if err != nil {
450			return err
451		}
452		owner, repo, err := parseGitHubRepo(repoURL)
453		if err != nil {
454			return err
455		}
456		_, err = h.q.UpsertGitHubSource(ctx, database.UpsertGitHubSourceParams{
457			WorkspaceID:   uid,
458			RepoURL:       repoURL,
459			RepoOwner:     owner,
460			RepoName:      repo,
461			DefaultBranch: &defaultBranch,
462		})
463		if err != nil {
464			return fmt.Errorf("upsert github source: %w", err)
465		}
466		return nil
467	}
468	
469	func firstSnapshotSourceError(snap *domain.WorkspaceSnapshot) error {
470		if snap == nil {
471			return domain.NewDatabaseError(domain.ErrAdapterInternal, "workspace import returned nil snapshot")
472		}
473		if len(snap.SourceErrors) == 0 {
474			return nil
475		}
476		return snap.SourceErrors[0]
477	}
478	
479	func (h *handler) recordSuccessfulRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch, commitSHA string) error {
480		commitPtr := commitSHA
481		runID, err := h.ensureSyncRun(ctx, payload, trigger, mode, branch, &commitPtr, true)
482		if err != nil {
483			return err
484		}
485		_, err = h.q.UpdateSyncRunSuccess(ctx, database.UpdateSyncRunSuccessParams{
486			ID:        runID,
487			CommitSha: &commitPtr,
488		})
489		if err != nil {
490			return fmt.Errorf("update sync run success: %w", err)
491		}
492		return nil
493	}
494	
495	func (h *handler) recordFailedRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch string, syncErr error) {
496		code := "WORKER_SYNC_FAILED"
497		message := syncErr.Error()
498		var sourceErr domain.SourceError
499		if errors.As(syncErr, &sourceErr) {
500			code = string(sourceErr.Code)
501			message = sourceErr.Message
502		}
503		runID, err := h.ensureSyncRun(ctx, payload, trigger, mode, branch, nil, false)
504		if err != nil {
505			log.Printf("ensure failed sync run failed workspace_id=%s error=%v original_error=%v", payload.WorkspaceID, err, syncErr)
506			return
507		}
508		if _, err := h.q.UpdateSyncRunFailed(ctx, database.UpdateSyncRunFailedParams{
509			ID:           runID,
510			ErrorCode:    &code,
511			ErrorMessage: &message,
512		}); err != nil {
513			log.Printf("update failed sync run failed workspace_id=%s error=%v original_error=%v", payload.WorkspaceID, err, syncErr)
514		}
515	}
516	
517	func (h *handler) ensureSyncRun(ctx context.Context, payload queue.WorkspaceSyncPayload, trigger, mode, branch string, commitSHA *string, requireRefs bool) (pgtype.UUID, error) {
518		if payload.SyncRunID != "" {
519			return pgUUID(payload.SyncRunID)
520		}
521		uid, err := pgUUID(payload.WorkspaceID)
522		if err != nil {
523			return pgtype.UUID{}, err
524		}
525		featureUUID, _, err := h.syncRunReferenceIDs(ctx, uid, payload.FeatureID, "")
526		if err != nil {
527			if requireRefs {
528				return pgtype.UUID{}, err
529			}
530			log.Printf("warn: could not resolve sync run feature ref workspace_id=%s feature_id=%s: %v",
531				payload.WorkspaceID, payload.FeatureID, err)
532			featureUUID = pgtype.UUID{}
533		}
534		branchPtr := branch
535		row, err := h.q.InsertSyncRun(ctx, database.InsertSyncRunParams{
536			WorkspaceID:  uid,
537			Trigger:      trigger,
538			Branch:       &branchPtr,
539			FeatureID:    featureUUID,
540			Mode:         mode,
541			Status:       "running",
542			CommitSha:    commitSHA,
543			ChangedPaths: []byte("[]"),
544		})
545		if err != nil {
546			return pgtype.UUID{}, fmt.Errorf("insert sync run: %w", err)
547		}
548		return row.ID, nil
549	}
550	
551	func slugify(name string) string {
552		lower := strings.ToLower(name)
553		re := regexp.MustCompile(`[^a-z0-9]+`)
554		slug := re.ReplaceAllString(lower, "-")
555		return strings.Trim(slug, "-")
556	}
557	
558	func pgUUID(raw string) (pgtype.UUID, error) {
559		var uid pgtype.UUID
560		if err := uid.Scan(raw); err != nil {
561			return pgtype.UUID{}, fmt.Errorf("invalid workspace_id %q: %w", raw, err)
562		}
563		return uid, nil
564	}
565	
566	func parseGitHubRepo(raw string) (string, string, error) {
567		u, err := url.Parse(raw)
568		if err != nil || u.Host == "" {
569			return "", "", fmt.Errorf("invalid GitHub repo URL: %s", raw)
570		}
571		if !strings.EqualFold(u.Host, "github.com") {
572			return "", "", fmt.Errorf("unsupported GitHub host: %s", u.Host)
573		}
574		parts := strings.Split(strings.Trim(u.Path, "/"), "/")
575		if len(parts) < 2 || parts[0] == "" || parts[1] == "" {
576			return "", "", fmt.Errorf("invalid GitHub repo URL path: %s", raw)
577		}
578		return parts[0], strings.TrimSuffix(parts[1], ".git"), nil
579	}
