376	// SaveSnapshot updates an existing workspace and upserts its child rows inside a single transaction.
377	func (a *Adapter) SaveSnapshot(ctx context.Context, workspaceID string, snapshot *domain.WorkspaceSnapshot) error {
378		uid, err := parseUUID(workspaceID)
379		if err != nil {
380			return err
381		}
382		if _, err := a.q.GetWorkspace(ctx, uid); err != nil {
383			if errors.Is(err, pgx.ErrNoRows) {
384				return domain.NewDatabaseError(domain.ErrDatabaseNotFound, "workspace not found: "+workspaceID)
385			}
386			return dbErr("get workspace before save snapshot", err)
387		}
388	
389		tx, err := a.pool.BeginTx(ctx, pgx.TxOptions{})
390		if err != nil {
391			return fmt.Errorf("begin transaction: %w", err)
392		}
393		defer tx.Rollback(ctx) //nolint:errcheck
394	
395		if err := upsertSnapshot(ctx, a.q.WithTx(tx), uid, snapshot); err != nil {
396			return err
397		}
398		return tx.Commit(ctx)
399	}
