431			}
432	
433			// A task webhook can arrive before the feature branch/full workspace sync
434			// has materialized the parent feature row. In GitHub payloads, feature_id
435			// is the human-readable feature name; create a minimal feature row and let
436			// later feature/workspace sync enrich it while preserving UUID references.
437			feature, err := a.q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
438				WorkspaceID: uid,
