451		if err != nil {
452			return fmt.Errorf("begin transaction: %w", err)
453		}
454		defer tx.Rollback(ctx) //nolint:errcheck
455	
456		if err := upsertTaskSnapshot(ctx, a.q.WithTx(tx), uid, featureUUID, snap.FeatureID, snap); err != nil {
457			return err
458		}
459		return tx.Commit(ctx)
460	}
