462	// GetActiveSnapshot returns the latest WorkspaceSnapshot reconstructed from core tables.
463	func (a *Adapter) GetActiveSnapshot(ctx context.Context, workspaceID string) (*domain.WorkspaceSnapshot, error) {
464		uid, err := parseUUID(workspaceID)
465		if err != nil {
466			return nil, err
467		}
468	
469		ws, err := a.q.GetWorkspace(ctx, uid)
470		if err != nil {
471			if errors.Is(err, pgx.ErrNoRows) {
472				return nil, nil
473			}
474			return nil, dbErr("get workspace", err)
475		}
476	
477		features, err := a.q.ListWorkspaceFeatures(ctx, uid)
478		if err != nil {
479			return nil, dbErr("list features for snapshot", err)
480		}
481	
482		repos, err := a.q.ListWorkspaceRepos(ctx, uid)
483		if err != nil {
484			return nil, dbErr("list repos for snapshot", err)
485		}
486	
487		src, srcErr := a.q.GetGitHubSource(ctx, uid)
488		if srcErr != nil && !errors.Is(srcErr, pgx.ErrNoRows) {
489			log.Printf("warn: get github source workspace=%s: %v", workspaceID, srcErr)
490		}
491	
492		// Pre-fetch all docs and tasks in two queries to avoid N+1 per feature.
493		allDocs, err := a.q.ListWorkspaceFeatureDocuments(ctx, uid)
494		if err != nil {
495			return nil, dbErr("list docs for snapshot", err)
496		}
497		allTasks, err := a.q.ListWorkspaceTasks(ctx, uid)
498		if err != nil {
499			return nil, dbErr("list tasks for snapshot", err)
500		}
501	
502		// Group by feature_name (the legacy slug) for O(1) lookup inside buildFeatureSnapshotFromBatch.
503		docsByFeature := make(map[string][]database.WorkspaceFeatureDocument, len(features))
504		for _, d := range allDocs {
505			docsByFeature[d.FeatureName] = append(docsByFeature[d.FeatureName], d)
506		}
507		tasksByFeature := make(map[string][]database.WorkspaceTask, len(features))
508		for _, t := range allTasks {
509			tasksByFeature[t.FeatureName] = append(tasksByFeature[t.FeatureName], t)
510		}
511	
512		featureSnapshots := make([]domain.FeatureSnapshot, 0, len(features))
513		for _, f := range features {
514			fs := buildFeatureSnapshotFromBatch(f, docsByFeature[f.FeatureName], tasksByFeature[f.FeatureName])
515			featureSnapshots = append(featureSnapshots, fs)
516		}
517	
518		repoEntries := make([]domain.RepoEntry, 0, len(repos))
519		for _, r := range repos {
520			re := domain.RepoEntry{RepoID: r.RepoID}
521			if r.BaseBranch != nil {
522				re.BaseBranch = *r.BaseBranch
523			}
524			repoEntries = append(repoEntries, re)
525		}
526	
527		repoURL := ""
528		if src.RepoURL != "" {
529			repoURL = src.RepoURL
530		}
531	
532		return &domain.WorkspaceSnapshot{
533			WorkspaceID:      workspaceID,
534			Name:             ws.Name,
535			Slug:             ws.Slug,
536			RepoURL:          repoURL,
537			ManagementRepoID: ws.ManagementRepoID,
538			BranchPattern:    derefStr(ws.BranchPattern),
539			Features:         featureSnapshots,
540			Repos:            repoEntries,
541		}, nil
542	}
