561	// upsertSnapshot is the transactional core of SaveSnapshot.
562	func upsertSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, snap *domain.WorkspaceSnapshot) error {
563		mgmtRepoID := snap.ManagementRepoID
564		if mgmtRepoID == "" {
565			mgmtRepoID = "management-repo"
566		}
567		_, err := q.UpdateWorkspaceByID(ctx, database.UpdateWorkspaceByIDParams{
568			ID:               uid,
569			Slug:             snap.Slug,
570			Name:             snap.Name,
571			ManagementRepoID: mgmtRepoID,
572			BranchPattern:    ptrStr(snap.BranchPattern),
573		})
574		if err != nil {
575			if errors.Is(err, pgx.ErrNoRows) {
576				return domain.NewDatabaseError(domain.ErrDatabaseNotFound, "workspace not found: "+uuidStr(uid))
577			}
578			return fmt.Errorf("update workspace: %w", err)
579		}
580	
581		// Upsert repos.
582		repoIDs := make([]string, 0, len(snap.Repos))
583		for _, r := range snap.Repos {
584			bp := ptrStr(r.BaseBranch)
585			_, err := q.UpsertWorkspaceRepo(ctx, database.UpsertWorkspaceRepoParams{
586				WorkspaceID: uid,
587				RepoID:      r.RepoID,
588				BaseBranch:  bp,
589			})
590			if err != nil {
591				return fmt.Errorf("upsert repo %s: %w", r.RepoID, err)
592			}
593			repoIDs = append(repoIDs, r.RepoID)
594		}
595		if err := q.DeleteWorkspaceReposNotIn(ctx, database.DeleteWorkspaceReposNotInParams{
596			WorkspaceID: uid,
597			RepoIds:     repoIDs,
598		}); err != nil {
599			return fmt.Errorf("delete stale repos: %w", err)
600		}
601	
602		// Upsert features, docs, tasks, activity.
603		featureIDs := make([]string, 0, len(snap.Features))
604		for _, f := range snap.Features {
605			if err := upsertFeatureSnapshot(ctx, q, uid, f); err != nil {
606				return err
607			}
608			featureIDs = append(featureIDs, f.FeatureID)
609		}
610		if err := q.DeleteWorkspaceFeaturesNotIn(ctx, database.DeleteWorkspaceFeaturesNotInParams{
611			WorkspaceID:  uid,
612			FeatureNames: featureIDs,
613		}); err != nil {
614			return fmt.Errorf("delete stale features: %w", err)
615		}
616	
617		return nil
618	}
