620	func upsertFeatureSnapshot(ctx context.Context, q *database.Queries, uid pgtype.UUID, f domain.FeatureSnapshot) error {
621		stages, err := json.Marshal(f.Stages)
622		if err != nil {
623			return fmt.Errorf("marshal stages for feature %s: %w", f.FeatureID, err)
624		}
625		featureRow, err := q.UpsertWorkspaceFeature(ctx, database.UpsertWorkspaceFeatureParams{
626			WorkspaceID:   uid,
627			FeatureName:   f.FeatureID,
628			Title:         f.Title,
629			FeatureStatus: ptrStr(f.Status),
630			CurrentStage:  ptrStr(f.CurrentStage),
631			NextAction:    ptrStr(f.NextAction),
632			Stages:        stages,
633			SourcePath:    f.SourcePath,
634			SourceHash:    ptrStr(f.SourceHash),
635		})
636		if err != nil {
637			return fmt.Errorf("upsert feature %s: %w", f.FeatureID, err)
638		}
639	
640		// Upsert documents.
641		docTypes := make([]string, 0, len(f.Documents))
642		for _, d := range f.Documents {
643			_, err := q.UpsertFeatureDocument(ctx, database.UpsertFeatureDocumentParams{
644				WorkspaceID:  uid,
645				FeatureID:    featureRow.ID,
646				FeatureName:  f.FeatureID,
647				DocumentType: d.DocumentType,
648				SourcePath:   d.SourcePath,
649				URL:          ptrStr(d.URL),
650			})
651			if err != nil {
652				return fmt.Errorf("upsert document %s/%s: %w", f.FeatureID, d.DocumentType, err)
653			}
654			docTypes = append(docTypes, d.DocumentType)
655		}
656		if err := q.DeleteFeatureDocumentsNotIn(ctx, database.DeleteFeatureDocumentsNotInParams{
657			WorkspaceID:   uid,
658			FeatureID:     featureRow.ID,
659			DocumentTypes: docTypes,
660		}); err != nil {
661			return fmt.Errorf("delete stale documents for %s: %w", f.FeatureID, err)
662		}
663	
664		// Upsert tasks.
665		taskIDs := make([]string, 0, len(f.Tasks))
666		for _, t := range f.Tasks {
667			if err := upsertTaskSnapshot(ctx, q, uid, featureRow.ID, f.FeatureID, t); err != nil {
668				return err
669			}
670			taskIDs = append(taskIDs, t.TaskID)
671		}
672		if err := q.DeleteFeatureTasksNotIn(ctx, database.DeleteFeatureTasksNotInParams{
673			WorkspaceID: uid,
674			FeatureID:   featureRow.ID,
675			TaskNames:   taskIDs,
676		}); err != nil {
677			return fmt.Errorf("delete stale tasks for %s: %w", f.FeatureID, err)
678		}
679	
680		// Upsert feature-level activity (task_id = nil).
681		if err := upsertFeatureActivity(ctx, q, uid, featureRow.ID, f); err != nil {
682			return err
683		}
684	
685		return nil
686	}
