773	// buildFeatureSnapshotFromBatch reconstructs a FeatureSnapshot from pre-fetched rows,
774	// avoiding per-feature database queries.
775	func buildFeatureSnapshotFromBatch(f database.WorkspaceFeature, docs []database.WorkspaceFeatureDocument, tasks []database.WorkspaceTask) domain.FeatureSnapshot {
776		docSnaps := make([]domain.DocumentSnapshot, 0, len(docs))
777		for _, d := range docs {
778			ds := domain.DocumentSnapshot{
779				DocumentType: d.DocumentType,
780				SourcePath:   d.SourcePath,
781			}
782			if d.URL != nil {
783				ds.URL = *d.URL
784			}
785			docSnaps = append(docSnaps, ds)
786		}
787	
788		taskSnaps := make([]domain.TaskSnapshot, 0, len(tasks))
789		for _, t := range tasks {
790			taskSnaps = append(taskSnaps, rowToTaskSnapshot(t))
791		}
792	
793		fs := domain.FeatureSnapshot{
794			FeatureID:  f.FeatureName,
795			Title:      f.Title,
796			SourcePath: f.SourcePath,
797			Documents:  docSnaps,
798			Tasks:      taskSnaps,
799		}
800		if f.FeatureStatus != nil {
801			fs.Status = *f.FeatureStatus
802		}
803		if f.CurrentStage != nil {
804			fs.CurrentStage = *f.CurrentStage
805		}
806		if f.NextAction != nil {
807			fs.NextAction = *f.NextAction
808		}
809		if len(f.Stages) > 0 {
810			var stages map[string]interface{}
811			if err := json.Unmarshal(f.Stages, &stages); err == nil {
812				fs.Stages = stages
813			}
814		}
815		if f.SourceHash != nil {
816			fs.SourceHash = *f.SourceHash
817		}
818		return fs
819	}
