863	// rowToFeatureSummary converts feature row + task list to a domain.FeatureSummary.
864	func rowToFeatureSummary(f database.WorkspaceFeature, tasks []database.WorkspaceTask) domain.FeatureSummary {
865		counts := domain.TaskCounts{}
866		for _, t := range tasks {
867			if t.FeatureName != f.FeatureName {
868				continue
869			}
870			counts.Total++
871			if t.Status == nil {
872				continue
873			}
874			switch *t.Status {
875			case "done":
876				counts.Done++
877			case "in_progress":
878				counts.InProgress++
879			case "blocked":
880				counts.Blocked++
881			case "ready":
882				counts.Ready++
883			case "todo":
884				counts.Todo++
885			}
886		}
887	
888		fs := domain.FeatureSummary{
889			ID:          uuidStr(f.ID),
890			FeatureID:   uuidStr(f.FeatureID),
891			FeatureName: f.FeatureName,
892			Title:       f.Title,
893			UpdatedAt:   f.UpdatedAt.Time,
894			TaskCounts:  counts,
895		}
896		if f.FeatureStatus != nil {
897			fs.Status = *f.FeatureStatus
898		}
899		if f.CurrentStage != nil {
900			fs.CurrentStage = *f.CurrentStage
901		}
902		return fs
903	}
