1070	// uuidStr renders a pgtype.UUID as a lowercase hyphenated string.
1071	func uuidStr(u pgtype.UUID) string {
1072		if !u.Valid {
1073			return ""
1074		}
1075		b := u.Bytes
1076		return fmt.Sprintf("%08x-%04x-%04x-%04x-%012x",
1077			b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
1078	}
1079	
1080	// ptrStr returns nil if s is empty, otherwise returns &s.
1081	func ptrStr(s string) *string {
1082		if s == "" {
1083			return nil
1084		}
1085		return &s
1086	}
1087	
1088	func derefStr(s *string) string {
1089		if s == nil {
1090			return ""
1091		}
1092		return *s
1093	}
1094	
1095	// unmarshalStringSlice decodes a JSON array of strings.
1096	func unmarshalStringSlice(raw json.RawMessage) []string {
1097		if len(raw) == 0 {
1098			return nil
1099		}
1100		var out []string
1101		_ = json.Unmarshal(raw, &out)
1102		return out
1103	}
1104	
1105	// unmarshalExecution decodes execution JSON into domain.ExecutionContext.
1106	func unmarshalExecution(raw json.RawMessage) domain.ExecutionContext {
1107		if len(raw) == 0 {
1108			return domain.ExecutionContext{}
1109		}
1110		var ec domain.ExecutionContext
1111		_ = json.Unmarshal(raw, &ec)
1112		return ec
1113	}
1114	
1115	// dbErr wraps a database error in a domain SourceError.
1116	func dbErr(op string, err error) error {
1117		if strings.Contains(err.Error(), "no rows") {
1118			return domain.NewDatabaseError(domain.ErrDatabaseNotFound, op+": not found")
1119		}
1120		return domain.NewDatabaseError(domain.ErrDatabaseQuery, op+": "+err.Error())
1121	}
